export function boundOk(p, b, o) {
    // A bound (region, a, b) at word o: region 0..5; infinities are 0, 0; a
    // big magnitude is a pool range of length >= 9 without a leading zero.
    const r = pw(p, o);
    const a = pw(p, o + 1);
    const c = pw(p, o + 2);
    if ((r < 0) || (r > 5)) {
        return false;
    }
    if ((r === 0) || (r === 5)) {
        return (a === 0) && (c === 0);
    }
    if ((r === 1) || (r === 4)) {
        return (byteRange(b, a, c) && (c >= 9)) && ((c <= 4096) && (b[a] !== 0));
    }
    return true;
}

export function u64Cmp(ahi, alo, bhi, blo) {
    if (ahi !== bhi) {
        if ((ahi >>> 0) < (bhi >>> 0)) {
            return -1;
        }
        return 1;
    }
    if (alo !== blo) {
        if ((alo >>> 0) < (blo >>> 0)) {
            return -1;
        }
        return 1;
    }
    return 0;
}

export function magCmp(b, o1, l1, o2, l2) {
    if (l1 !== l2) {
        return l1 - l2;
    }
    return bytesCmp(b, o1, l1, o2, l2);
}

export function bcmp(p, b, x, y) {
    // Compare the (valid) bounds at words x and y.
    const rx = pw(p, x);
    const ry = pw(p, y);
    if (rx !== ry) {
        if (rx < ry) {
            return -1;
        }
        return 1;
    }
    if (rx === 3) {
        return u64Cmp(pw(p, x + 1), pw(p, x + 2), pw(p, y + 1), pw(p, y + 2));
    }
    if (rx === 2) {
        return u64Cmp(pw(p, y + 1), pw(p, y + 2), pw(p, x + 1), pw(p, x + 2));
    }
    if (rx === 4) {
        return magCmp(b, pw(p, x + 1), pw(p, x + 2), pw(p, y + 1), pw(p, y + 2));
    }
    if (rx === 1) {
        return magCmp(b, pw(p, y + 1), pw(p, y + 2), pw(p, x + 1), pw(p, x + 2));
    }
    return 0;
}

export function magSucc(b, vo, vl, wo, wl) {
    // Is magnitude w = magnitude v + 1?
    if (wl === (vl + 1)) {
        if (b[wo] !== 1) {
            return false;
        }
        for (let k = 0; k < vl; k++) {
            if ((b[vo + k] !== 255) || (b[wo + (k + 1)] !== 0)) {
                return false;
            }
        }
        return true;
    }
    if (wl !== vl) {
        return false;
    }
    let i = vl - 1;
    while ((i >= 0) && ((b[vo + i] === 255) && (b[wo + i] === 0))) {
        i -= 1;
    }
    if (i < 0) {
        return false;
    }
    if ((b[vo + i] + 1) !== b[wo + i]) {
        return false;
    }
    for (let j = 0; j < i; j++) {
        if (b[vo + j] !== b[wo + j]) {
            return false;
        }
    }
    return true;
}

export function isSucc(p, b, x, y) {
    // Is the bound at y exactly one more than the (finite) bound at x?
    const rx = pw(p, x);
    const ax = pw(p, x + 1);
    const cx = pw(p, x + 2);
    const ry = pw(p, y);
    const ay = pw(p, y + 1);
    const cy = pw(p, y + 2);
    if ((rx === 3) && (ry === 3)) {
        const lo = (cx + 1) | 0;
        let hi = ax;
        if (cx === (-1)) {
            hi = (ax + 1) | 0;
        }
        if (cx === (-1)) {
            if (ax === (-1)) {
                return false;
            }
        }
        return (ay === hi) && (cy === (lo | 0));
    }
    if ((rx === 3) && (ry === 4)) {
        return ((ax === (-1)) && (cx === (-1))) && ((cy === 9) && ((b[ay] === 1) && (((b[ay + 1] | b[ay + 2]) === 0) && (((b[ay + 3] | b[ay + 4]) === 0) && (((b[ay + 5] | b[ay + 6]) === 0) && ((b[ay + 7] | b[ay + 8]) === 0))))));
    }
    if ((rx === 2) && (ry === 3)) {
        return ((ax === 0) && (cx === 0)) && ((ay === 0) && (cy === 0));
    }
    if ((rx === 2) && (ry === 2)) {
        // value + 1 means n - 1
        if ((ax === 0) && (cx === 0)) {
            return false;
        }
        const lo2 = (cx - 1) | 0;
        let hi2 = ax;
        if (cx === 0) {
            hi2 = (ax - 1) | 0;
        }
        return (ay === hi2) && (cy === lo2);
    }
    if ((rx === 1) && (ry === 2)) {
        return ((ay === (-1)) && (cy === (-1))) && ((cx === 9) && ((b[ax] === 1) && (((b[ax + 1] | b[ax + 2]) === 0) && (((b[ax + 3] | b[ax + 4]) === 0) && (((b[ax + 5] | b[ax + 6]) === 0) && ((b[ax + 7] | b[ax + 8]) === 0))))));
    }
    if ((rx === 1) && (ry === 1)) {
        return magSucc(b, ay, cy, ax, cx);
    }
    if ((rx === 4) && (ry === 4)) {
        return magSucc(b, ax, cx, ay, cy);
    }
    return false;
}

export function checkIvRecords(p, b, s) {
    const base = sec(p, 13);
    const n = pw(p, W_N_INTERVALS);
    for (let i = 0; i < n; i++) {
        const o = base + (6 * i);
        if (!spend(s, 4)) {
            return false;
        }
        if ((!boundOk(p, b, o)) || (!boundOk(p, b, o + 3))) {
            bad(s, o, C_INTERVAL);
            return false;
        }
        if (bcmp(p, b, o, o + 3) > 0) {
            bad(s, o, C_INTERVAL);
            return false;
        }
    }
    const fb = sec(p, 14);
    const nf = pw(p, W_N_FINTERVALS);
    for (let j = 0; j < nf; j++) {
        const fo = fb + (4 * j);
        if (u64Cmp(pw(p, fo), pw(p, fo + 1), pw(p, fo + 2), pw(p, fo + 3)) > 0) {
            bad(s, fo, C_FINTERVAL);
            return false;
        }
    }
    return !failed(s);
}

export function ivRunOk(p, b, s, first, n) {
    // A leaf's interval run: in range, ascending, disjoint, non-adjacent.
    if ((first < 0) || ((n < 0) || (n > (pw(p, W_N_INTERVALS) - first)))) {
        return false;
    }
    const base = sec(p, 13);
    for (let i = 1; i < n; i++) {
        const pv = base + (6 * (first + (i - 1)));
        const cu = base + (6 * (first + i));
        if (!spend(s, 2)) {
            return false;
        }
        if (bcmp(p, b, cu, pv + 3) <= 0) {
            return false;
        }
        if (pw(p, pv + 3) === 5) {
            return false;
        }
        if (isSucc(p, b, pv + 3, cu)) {
            return false;
        }
    }
    return true;
}

export function fivRunOk(p, first, n) {
    if ((first < 0) || ((n < 0) || (n > (pw(p, W_N_FINTERVALS) - first)))) {
        return false;
    }
    const base = sec(p, 14);
    for (let i = 1; i < n; i++) {
        const pv = base + (4 * (first + (i - 1)));
        const cu = base + (4 * (first + i));
        const ph = pw(p, pv + 2);
        const pl = pw(p, pv + 3);
        const nl = (pl + 1) | 0;
        let nh = ph;
        if (pl === (-1)) {
            nh = (ph + 1) | 0;
        }
        if ((ph === (-1)) && (pl === (-1))) {
            return false;
        }
        if (u64Cmp(pw(p, cu), pw(p, cu + 1), ph, pl) <= 0) {
            return false;
        }
        if ((pw(p, cu) === (nh | 0)) && (pw(p, cu + 1) === (nl | 0))) {
            return false;
        }
    }
    return true;
}

export function ivMask(p, first, n, bigok) {
    // The INT class mask of a (checked) interval run.
    const base = sec(p, 13);
    let m = 0;
    for (let i = 0; i < n; i++) {
        const o = base + (6 * (first + i));
        const lr = pw(p, o);
        const hr = pw(p, o + 3);
        if ((lr <= 3) && (hr >= 3)) {
            m |= 1;
        }
        if ((lr <= 2) && (hr >= 2)) {
            m |= 2;
        }
        if (bigok !== 0) {
            if (((lr <= 1) && (hr >= 1)) || ((lr <= 4) && (hr >= 4))) {
                m |= 2048;
            }
        }
    }
    return m;
}

export function zeroFrom(p, o, k) {
    // Are leaf words d_k .. d5 (o + 2 + k .. o + 7) all zero?
    for (let i = 2 + k; i < 8; i++) {
        if (pw(p, o + i) !== 0) {
            return false;
        }
    }
    return true;
}

export function leafMaskOf(p, b, l) {
    // The derived mask of leaf l (fields already checked), -1 if invalid.
    const o = leafAt(p, l);
    const k = pw(p, o) & 255;
    const fl = (pw(p, o) >> 8) & 255;
    const d0 = pw(p, o + 2);
    const d1 = pw(p, o + 3);
    if (k === 1) {
        return 4095;
    }
    if (k === 2) {
        if (d0 === 6) {
            return 2112;
        }
        if (d0 === 7) {
            return 1920;
        }
        return 1 << d0;
    }
    if (k === 3) {
        return ivMask(p, d0, d1, fl);
    }
    if (k === 4) {
        return fl << 8;
    }
    if (k === 5) {
        return 128;
    }
    if (k === 6) {
        return encClass(b, d0);
    }
    if (k === 7) {
        const lr = sec(p, 15) + (2 * d0);
        return encClass(b, pw(p, lr));
    }
    if (k === 8) {
        return 8;
    }
    if ((k === 9) || (k === 13)) {
        return 4;
    }
    if (k === 10) {
        return 1;
    }
    if (k === 11) {
        if ((d0 === 0) && ((d1 === 2) || (d1 === 3))) {
            return 2048;
        }
        return 64;
    }
    if (k === 12) {
        const lohi = d0;
        const lolo = d1;
        const hihi = pw(p, o + 4);
        const hilo = pw(p, o + 5);
        let m = 0;
        if (((lohi !== 0) || (hihi !== 0)) || (((lolo >>> 0) < (2 >>> 0)) || ((3 >>> 0) < (hilo >>> 0)))) {
            m |= 64;
        }
        if (((lohi === 0) && ((lolo >>> 0) < (4 >>> 0))) && ((hihi !== 0) || (!((hilo >>> 0) < (2 >>> 0))))) {
            m |= 2048;
        }
        return m;
    }
    if (k === 14) {
        return 16;
    }
    if (k === 15) {
        return 32;
    }
    if (k === 18) {
        return 4095;
    }
    return 0;
}

export function checkLeaf(p, b, s, l) {
    const o = leafAt(p, l);
    const w0 = pw(p, o);
    const k = w0 & 255;
    const fl = (w0 >> 8) & 255;
    const d0 = pw(p, o + 2);
    const d1 = pw(p, o + 3);
    const d2 = pw(p, o + 4);
    const d3 = pw(p, o + 5);
    const d4 = pw(p, o + 6);
    const nl = pw(p, W_N_LEAVES);
    const nt = pw(p, W_N_TYPESETS);
    if (!spend(s, 8)) {
        return false;
    }
    if (((k < 1) || (k > 18)) || ((w0 >> 16) !== 0)) {
        return want(s, false, o, C_LEAF);
    }
    if ((k === 18) && (!v11(p))) {
        return want(s, false, o, C_LEAF);
    }
    if (pw(p, o + 7) !== 0) {
        return want(s, false, o, C_LEAF);
    }
    if (((k !== 3) && (k !== 4)) && ((k !== 13) && (fl !== 0))) {
        return want(s, false, o, C_LEAF);
    }
    if (k === 1) {
        return want(s, zeroFrom(p, o, 0), o, C_LEAF);
    }
    if (k === 2) {
        return want(s, ((d0 >= 0) && (d0 <= 7)) && zeroFrom(p, o, 1), o, C_LEAF);
    }
    if (k === 3) {
        const runOk = ivRunOk(p, b, s, d0, d1);
        return want(s, ((fl <= 1) && (d1 >= 1)) && (runOk && zeroFrom(p, o, 2)), o, C_LEAF);
    }
    if (k === 4) {
        if ((fl < 1) || (fl > 7)) {
            return want(s, false, o, C_LEAF);
        }
        if (d1 === 0) {
            return want(s, zeroFrom(p, o, 0), o, C_LEAF);
        }
        return want(s, fivRunOk(p, d0, d1) && zeroFrom(p, o, 2), o, C_LEAF);
    }
    if (k === 5) {
        return want(s, ((d0 >= 0) && (d0 <= 23)) && zeroFrom(p, o, 1), o, C_LEAF);
    }
    if (k === 6) {
        return want(s, (byteRange(b, d0, d1) && (d1 >= 1)) && zeroFrom(p, o, 2), o, C_LEAF);
    }
    if (k === 7) {
        if (((d0 < 0) || (d1 < 2)) || (d1 > (pw(p, W_N_LITREFS) - d0))) {
            return want(s, false, o, C_LEAF);
        }
        if (!zeroFrom(p, o, 2)) {
            return want(s, false, o, C_LEAF);
        }
        const lb = sec(p, 15);
        let cls = 0;
        for (let i = 0; i < d1; i++) {
            const mo = pw(p, lb + (2 * (d0 + i)));
            const ml = pw(p, lb + ((2 * (d0 + i)) + 1));
            if ((!byteRange(b, mo, ml)) || (ml < 1)) {
                return want(s, false, o, C_LITREF);
            }
            if (i === 0) {
                cls = encClass(b, mo);
            }
            if (encClass(b, mo) !== cls) {
                return want(s, false, o, C_LITREF);
            }
            if (i > 0) {
                const po = pw(p, lb + (2 * (d0 + (i - 1))));
                const pl = pw(p, lb + ((2 * (d0 + (i - 1))) + 1));
                if (bytesCmp(b, po, pl, mo, ml) >= 0) {
                    return want(s, false, o, C_LITREF);
                }
            }
        }
        return true;
    }
    if (k === 8) {
        return want(s, (((d0 >= 0) && (d1 >= d0)) && ((d2 >= (-1)) && (d2 < pw(p, W_N_REGEXPS)))) && zeroFrom(p, o, 3), o, C_LEAF);
    }
    if (k === 9) {
        if ((d0 < 0) || (d1 < d0)) {
            return want(s, false, o, C_LEAF);
        }
        if (d3 === 0) {
            return want(s, zeroFrom(p, o, 2), o, C_LEAF);
        }
        return want(s, byteRange(b, d2, d3) && zeroFrom(p, o, 4), o, C_LEAF);
    }
    if (k === 10) {
        if (d3 === 0) {
            return want(s, (d2 === 0) && zeroFrom(p, o, 4), o, C_LEAF);
        }
        const runOk2 = ivRunOk(p, b, s, d2, d3);
        return want(s, runOk2 && zeroFrom(p, o, 4), o, C_LEAF);
    }
    if (k === 11) {
        return want(s, inRange(d2, nt) && zeroFrom(p, o, 3), o, C_LEAF);
    }
    if (k === 12) {
        return want(s, (u64Cmp(d0, d1, d2, d3) <= 0) && (inRange(d4, nt) && zeroFrom(p, o, 5)), o, C_LEAF);
    }
    if (k === 13) {
        return want(s, (fl <= 1) && (inRange(d0, nt) && zeroFrom(p, o, 1)), o, C_LEAF);
    }
    if (k === 14) {
        return want(s, inRange(d0, pw(p, W_N_ARRAYS)) && zeroFrom(p, o, 1), o, C_LEAF);
    }
    if (k === 15) {
        return want(s, inRange(d0, pw(p, W_N_MAPS)) && zeroFrom(p, o, 1), o, C_LEAF);
    }
    if (k === 16) {
        return want(s, (inRange(d0, nl) && inRange(d1, nl)) && zeroFrom(p, o, 2), o, C_LEAF);
    }
    if (k === 18) {
        // EXT (D140): control id, argument bytes (at least one), maximum item bytes
        return want(s, (inRange(d0, pw(p, W_N_EXTS)) && (byteRange(b, d1, d2) && (d2 >= 1))) && ((d3 >= 0) && zeroFrom(p, o, 4)), o, C_LEAF);
    }
    if (inRange(d0, nl) && inRange(d1, nl)) {
        return want(s, (leafKind(p, d1) === 6) && zeroFrom(p, o, 2), o, C_LEAF);
    }
    return want(s, false, o, C_LEAF);
}

export function checkLeaves(p, b, s) {
    const nl = pw(p, W_N_LEAVES);
    for (let l = 0; l < nl; l++) {
        if (!checkLeaf(p, b, s, l)) {
            return false;
        }
    }
    // masks, derived (AND/NOT need their operands' masks: computed in a second pass)
    for (let l2 = 0; l2 < nl; l2++) {
        const o = leafAt(p, l2);
        const k = pw(p, o) & 255;
        if ((k !== 16) && (k !== 17)) {
            if (pw(p, o + 1) !== leafMaskOf(p, b, l2)) {
                return want(s, false, o + 1, C_MASK);
            }
        }
    }
    for (let l3 = 0; l3 < nl; l3++) {
        const o3 = leafAt(p, l3);
        const k3 = pw(p, o3) & 255;
        if ((k3 === 16) || (k3 === 17)) {
            // AND: mask(a) & mask(b), NOT: mask(target), over the operands' stored
            // masks (each verified in turn, so the whole set is consistent).
            const ma = pw(p, leafAt(p, pw(p, o3 + 2)) + 1);
            const mb = pw(p, leafAt(p, pw(p, o3 + 3)) + 1);
            let m = ma;
            if (k3 === 16) {
                m = ma & mb;
            }
            if (pw(p, o3 + 1) !== m) {
                return want(s, false, o3 + 1, C_MASK);
            }
        }
    }
    return !failed(s);
}

export function checkKeys(p, b, s) {
    const base = sec(p, 4);
    const n = pw(p, W_N_KEYS);
    for (let i = 0; i < n; i++) {
        const o = base + (2 * i);
        const off = pw(p, o);
        const len = pw(p, o + 1);
        if (!spend(s, 2 + ((len / 8) | 0))) {
            return false;
        }
        if ((!byteRange(b, off, len)) || (len < 1)) {
            return want(s, false, o, C_KEY);
        }
        const m = (b[off] >>> 5) | 0;
        const he = headEnd(b, off, off + len);
        if (he < 0) {
            return want(s, false, o, C_KEY);
        }
        if (m <= 1) {
            if (he !== (off + len)) {
                return want(s, false, o, C_KEY);
            }
        } else {
            if (m !== 3) {
                return want(s, false, o, C_KEY);
            }
            const cl = headLenArg(b, off);
            if ((cl < 0) || ((he + cl) !== (off + len))) {
                return want(s, false, o, C_KEY);
            }
            if (!utf8Ok(b, he, off + len)) {
                return want(s, false, o, C_UTF8);
            }
        }
        if (i > 0) {
            if (bytesCmp(b, pw(p, o - 2), pw(p, o - 1), off, len) >= 0) {
                return want(s, false, o, C_KEY);
            }
        }
    }
    return !failed(s);
}

export function checkGroups(p, s) {
    const ng = pw(p, W_N_GROUPS);
    const nt = pw(p, W_N_TYPESETS);
    let empty = -1;
    for (let g = 0; g < ng; g++) {
        const o = rec(p, 5, g);
        const n = pw(p, o);
        let nc = 0;
        if (!spend(s, 1 + n)) {
            return false;
        }
        if ((n === 0) && (empty < 0)) {
            empty = g;
        }
        for (let i = 0; i < n; i++) {
            const e = o + (2 + (4 * i));
            const mn = pw(p, e + 2);
            const mx = pw(p, e + 3);
            if ((!inRange(pw(p, e), nt)) || (!inRange(pw(p, e + 1), nt))) {
                return want(s, false, e, C_GROUP);
            }
            if ((mn < 0) || ((mn > mx) || (mx < 1))) {
                return want(s, false, e, C_GROUP);
            }
            if ((mx !== INF) && (mx >= 16777216)) {
                return want(s, false, e, C_GROUP);
            }
            if (!((mn === 0) && (mx === INF))) {
                nc += 1;
            }
        }
        if (pw(p, o + 1) !== nc) {
            return want(s, false, o + 1, C_DERIVED);
        }
    }
    if (pw(p, W_G_EMPTY) !== empty) {
        return want(s, false, W_G_EMPTY, C_HEADER);
    }
    return !failed(s);
}

export function checkRules(p, b, s) {
    const base = sec(p, 0);
    const n = pw(p, W_N_RULES);
    for (let i = 0; i < n; i++) {
        const o = base + (5 * i);
        const off = pw(p, o);
        const len = pw(p, o + 1);
        if (!spend(s, 2 + ((len / 8) | 0))) {
            return false;
        }
        if ((!byteRange(b, off, len)) || (len < 1)) {
            return want(s, false, o, C_RULE);
        }
        if (!utf8Ok(b, off, off + len)) {
            return want(s, false, o, C_UTF8);
        }
        if (i > 0) {
            if (bytesCmp(b, pw(p, o - 5), pw(p, o - 4), off, len) >= 0) {
                return want(s, false, o, C_RULE);
            }
        }
        if (!inRange(pw(p, o + 2), pw(p, W_N_TYPESETS))) {
            return want(s, false, o, C_RULE);
        }
        if (!inRange(pw(p, o + 3), pw(p, W_N_CHAINS))) {
            return want(s, false, o, C_RULE);
        }
    }
    return !failed(s);
}

export function ceil32(n) {
    return (n + 31) >> 5;
}

export function checkMap(p, s, m) {
    const o = rec(p, 7, m);
    const nf = pw(p, o);
    const np = pw(p, o + 1);
    const na = pw(p, o + 2);
    const nl = pw(p, o + 3);
    const nk = pw(p, o + 4);
    const nn = pw(p, o + 5);
    const fb = o + 8;
    const pb = fb + (4 * nf);
    const ab = pb + (5 * np);
    const lb = ab + (5 * na);
    const kb = lb + (4 * nl);
    const nb = kb + (4 * nk);
    const ng = pw(p, W_N_GROUPS);
    const nt = pw(p, W_N_TYPESETS);
    const nkeys = pw(p, W_N_KEYS);
    let sw = 4 + nf;
    let groupsum = 0;
    let maxnames = 0;
    if (!spend(s, (nf + np) + ((2 * na) + ((2 * nl) + (2 * nk))))) {
        return false;
    }
    // factors: 0 is RESIDUAL with pools from 0; the others own one pool each
    let nextpool = 0;
    for (let f = 0; f < nf; f++) {
        const fo = fb + (4 * f);
        const mode = pw(p, fo);
        const pp = pw(p, fo + 1);
        const pf = pw(p, fo + 2);
        const pc = pw(p, fo + 3);
        if (f === 0) {
            if ((mode !== 0) || (pc < 1)) {
                return want(s, false, fo, C_MAP);
            }
        } else {
            if ((mode < 1) || (mode > 2)) {
                return want(s, false, fo, C_MAP);
            }
            if (pc !== 1) {
                return want(s, false, fo, C_MAP);
            }
        }
        if (pf !== nextpool) {
            return want(s, false, fo, C_MAP);
        }
        if (mode === 2) {
            if ((pp !== 0) || (pw(p, fb + 3) !== 1)) {
                return want(s, false, fo, C_MAP);
            }
            if (pw(p, pb + 3) !== 1) {
                return want(s, false, fo, C_MAP);
            }
        } else if (pp !== (-1)) {
            return want(s, false, fo, C_MAP);
        }
        nextpool = pf + pc;
    }
    if (nextpool !== np) {
        return want(s, false, fb, C_MAP);
    }
    // pools: owners, groups, alternative runs partitioning alts; state offsets
    let nextalt = 0;
    let fi = 0;
    for (let q = 0; q < np; q++) {
        const po = pb + (5 * q);
        const f2 = pw(p, po);
        const g = pw(p, po + 1);
        const af = pw(p, po + 2);
        const ac = pw(p, po + 3);
        while ((fi < nf) && (q >= (pw(p, fb + ((4 * fi) + 2)) + pw(p, fb + ((4 * fi) + 3))))) {
            fi += 1;
        }
        if (f2 !== fi) {
            return want(s, false, po, C_MAP);
        }
        if (f2 === 0) {
            if (!inRange(g, ng)) {
                return want(s, false, po, C_MAP);
            }
            const gn = pw(p, rec(p, 5, g));
            if (pw(p, po + 4) !== sw) {
                return want(s, false, po + 4, C_DERIVED);
            }
            sw += 4 + gn;
            groupsum += gn;
        } else {
            if (g !== (-1)) {
                return want(s, false, po, C_MAP);
            }
            if (pw(p, po + 4) !== sw) {
                return want(s, false, po + 4, C_DERIVED);
            }
            sw += 4;
        }
        if ((af !== nextalt) || (ac < 1)) {
            return want(s, false, po, C_MAP);
        }
        nextalt = af + ac;
    }
    if (nextalt !== na) {
        return want(s, false, pb, C_MAP);
    }
    // alternatives: owners, literal runs (in range, not overlapping), req_count
    let pi = 0;
    for (let a = 0; a < na; a++) {
        const ao = ab + (5 * a);
        const lf = pw(p, ao + 1);
        const lc = pw(p, ao + 2);
        let req = 0;
        while ((pi < np) && (a >= (pw(p, pb + ((5 * pi) + 2)) + pw(p, pb + ((5 * pi) + 3))))) {
            pi += 1;
        }
        if (pw(p, ao) !== pi) {
            return want(s, false, ao, C_MAP);
        }
        if (((lf < 0) || (lc < 0)) || (lc > (nl - lf))) {
            return want(s, false, ao, C_MAP);
        }
        // runs do not overlap: each run starts at or after the previous one's end
        if (a > 0) {
            const pa = ao - 5;
            const pend = pw(p, pa + 1) + pw(p, pa + 2);
            if ((lf < pend) && (lc > 0)) {
                return want(s, false, ao, C_MAP);
            }
        }
        // (keys distinct within an alternative follows from the naming records:
        // each key's records name strictly ascending alternatives, and every
        // literal entry is named exactly once)
        for (let i = 0; i < lc; i++) {
            const le = lb + (4 * (lf + i));
            if (pw(p, le + 2) === 1) {
                req += 1;
            }
        }
        if (pw(p, ao + 3) !== req) {
            return want(s, false, ao + 3, C_DERIVED);
        }
        if (pw(p, ao + 4) !== sw) {
            return want(s, false, ao + 4, C_DERIVED);
        }
        sw += 3 + ceil32(lc);
    }
    // literal entries
    for (let i2 = 0; i2 < nl; i2++) {
        const le2 = lb + (4 * i2);
        if ((!inRange(pw(p, le2), nkeys)) || (!inRange(pw(p, le2 + 1), nt))) {
            return want(s, false, le2, C_MAP);
        }
        if (((pw(p, le2 + 2) < 0) || (pw(p, le2 + 2) > 1)) || ((pw(p, le2 + 3) < 0) || (pw(p, le2 + 3) > 1))) {
            return want(s, false, le2, C_MAP);
        }
    }
    // key index: ascending keys, naming runs partitioning names; each naming
    // record names its own key, in an alternative of the owner, ascending
    if (nn !== nl) {
        return want(s, false, o, C_MAP);
    }
    let nextname = 0;
    for (let kq = 0; kq < nk; kq++) {
        const ko = kb + (4 * kq);
        const key = pw(p, ko);
        const owner = pw(p, ko + 1);
        const nf2 = pw(p, ko + 2);
        const nc2 = pw(p, ko + 3);
        if (!inRange(key, nkeys)) {
            return want(s, false, ko, C_MAP);
        }
        if ((kq > 0) && (key <= pw(p, ko - 4))) {
            return want(s, false, ko, C_MAP);
        }
        if (!inRange(owner, nf)) {
            return want(s, false, ko, C_MAP);
        }
        if ((nf2 !== nextname) || ((nc2 < 1) || (nc2 > (nn - nf2)))) {
            return want(s, false, ko, C_MAP);
        }
        if (nc2 > maxnames) {
            maxnames = nc2;
        }
        for (let r = 0; r < nc2; r++) {
            const no = nb + (2 * (nf2 + r));
            const alt = pw(p, no);
            const lit = pw(p, no + 1);
            if (!inRange(alt, na)) {
                return want(s, false, no, C_MAP);
            }
            if ((r > 0) && (alt <= pw(p, no - 2))) {
                return want(s, false, no, C_MAP);
            }
            const ao2 = ab + (5 * alt);
            const lf2 = pw(p, ao2 + 1);
            const lc2 = pw(p, ao2 + 2);
            if ((lit < lf2) || (lit >= (lf2 + lc2))) {
                return want(s, false, no, C_MAP);
            }
            if (pw(p, lb + (4 * lit)) !== key) {
                return want(s, false, no, C_MAP);
            }
            // the owner is the alternative's pool's factor
            if (pw(p, pb + (5 * pw(p, ao2))) !== owner) {
                return want(s, false, no, C_MAP);
            }
        }
        nextname = nf2 + nc2;
    }
    if (nextname !== nn) {
        return want(s, false, kb, C_MAP);
    }
    // every key named by some literal entry is in the index: the counts agree
    if (pw(p, o + 6) !== sw) {
        return want(s, false, o + 6, C_DERIVED);
    }
    if (pw(p, o + 7) !== (groupsum + maxnames)) {
        return want(s, false, o + 7, C_DERIVED);
    }
    return !failed(s);
}

export function checkMaps(p, s) {
    for (let m = 0; m < pw(p, W_N_MAPS); m++) {
        if (!checkMap(p, s, m)) {
            return false;
        }
    }
    return true;
}

export function rowClean(p, at, w, npos) {
    // Bits >= npos of the w-word bitset at `at` are zero.
    if (w === 0) {
        return true;
    }
    const used = npos - (32 * (w - 1));
    if (used < 32) {
        const hi = pw(p, at + (w - 1));
        if (((hi >>> used) | 0) !== 0) {
            return false;
        }
    }
    return true;
}

export function checkArrays(p, s) {
    const na = pw(p, W_N_ARRAYS);
    const nt = pw(p, W_N_TYPESETS);
    for (let a = 0; a < na; a++) {
        const o = rec(p, 9, a);
        const npos = pw(p, o);
        const w = pw(p, o + 1);
        const nc = pw(p, o + 2);
        const nul = pw(p, o + 3);
        const fo = o + 4;
        const po = fo + (2 * w);
        const co = po + (2 * npos);
        const fl = co + (2 * nc);
        if (!spend(s, (npos * (w + 2)) + (nc * npos))) {
            return false;
        }
        if ((nul < 0) || (nul > 1)) {
            return want(s, false, o, C_ARRAY);
        }
        if ((!rowClean(p, fo, w, npos)) || (!rowClean(p, fo + w, w, npos))) {
            return want(s, false, fo, C_ARRAY);
        }
        for (let q = 0; q < npos; q++) {
            const ts = pw(p, po + (2 * q));
            const c = pw(p, po + ((2 * q) + 1));
            if (!inRange(ts, nt)) {
                return want(s, false, po + (2 * q), C_ARRAY);
            }
            if ((c < (-1)) || (c >= nc)) {
                return want(s, false, po + (2 * q), C_ARRAY);
            }
            if (!rowClean(p, fl + (q * w), w, npos)) {
                return want(s, false, fl + (q * w), C_ARRAY);
            }
            if (c >= 0) {
                // a counted position never has its own follow bit
                const word = pw(p, (fl + (q * w)) + (q >> 5));
                if ((((word >>> (q & 31)) | 0) & 1) !== 0) {
                    return want(s, false, fl + (q * w), C_ARRAY);
                }
            }
        }
        // each counter is used by exactly one position; 0 <= min, 1 <= max
        for (let ci = 0; ci < nc; ci++) {
            const cmin = pw(p, co + (2 * ci));
            const cmax = pw(p, co + ((2 * ci) + 1));
            let users = 0;
            if ((cmin < 0) || (cmax < 1)) {
                return want(s, false, co + (2 * ci), C_ARRAY);
            }
            for (let q2 = 0; q2 < npos; q2++) {
                if (pw(p, po + ((2 * q2) + 1)) === ci) {
                    users += 1;
                }
            }
            if (users !== 1) {
                return want(s, false, co + (2 * ci), C_ARRAY);
            }
        }
    }
    return !failed(s);
}

export function checkRegexps(p, s) {
    const nr = pw(p, W_N_REGEXPS);
    for (let r = 0; r < nr; r++) {
        const o = rec(p, 11, r);
        const npos = pw(p, o);
        const w = pw(p, o + 1);
        const natoms = pw(p, o + 2);
        const nul = pw(p, o + 3);
        const fo = o + 4;
        const fl = fo + (2 * w);
        const as = fl + (npos * w);
        const am = as + natoms;
        if (!spend(s, npos + natoms)) {
            return false;
        }
        if ((nul < 0) || (nul > 1)) {
            return want(s, false, o, C_REGEXP);
        }
        if ((!rowClean(p, fo, w, npos)) || (!rowClean(p, fo + w, w, npos))) {
            return want(s, false, fo, C_REGEXP);
        }
        for (let q = 0; q < npos; q++) {
            if (!rowClean(p, fl + (q * w), w, npos)) {
                return want(s, false, fl + (q * w), C_REGEXP);
            }
        }
        if (pw(p, as) !== 0) {
            return want(s, false, as, C_REGEXP);
        }
        for (let i = 0; i < natoms; i++) {
            const st = pw(p, as + i);
            if ((st < 0) || (st > 1114111)) {
                return want(s, false, as + i, C_REGEXP);
            }
            if ((i > 0) && (st <= pw(p, as + (i - 1)))) {
                return want(s, false, as + i, C_REGEXP);
            }
            if (!rowClean(p, am + (i * w), w, npos)) {
                return want(s, false, am + (i * w), C_REGEXP);
            }
        }
    }
    return !failed(s);
}

export function tsWithin(p, s, t, e) {
    // Is every leaf of t's evaluation list marked e?
    const n = tsEvalN(p, t);
    for (let i = 0; i < n; i++) {
        const l = tsEvalAt(p, t, i);
        if ((!inRange(l, pw(p, W_N_LEAVES))) || (markGet(s, l) !== e)) {
            return false;
        }
    }
    return true;
}

export function childTs(p, l, i) {
    // Child typeset i of leaf l (program.md §4.2's Children column), or -2 past
    // the last.
    const o = leafAt(p, l);
    const k = pw(p, o) & 255;
    const d0 = pw(p, o + 2);
    if ((k === 1) || ((k === 2) && ((d0 >= 4) && (d0 <= 6)))) {
        if (i === 0) {
            return pw(p, W_TS_ANY);
        }
        return -2;
    }
    if (k === 11) {
        if (i === 0) {
            return pw(p, o + 4);
        }
        return -2;
    }
    if (k === 12) {
        if (i === 0) {
            return pw(p, o + 6);
        }
        return -2;
    }
    if (k === 13) {
        if (i === 0) {
            return d0;
        }
        return -2;
    }
    if (k === 14) {
        const ao = rec(p, 9, d0);
        const npos = pw(p, ao);
        const w = pw(p, ao + 1);
        if (i >= npos) {
            return -2;
        }
        return pw(p, ((ao + 4) + (2 * w)) + (2 * i));
    }
    if (k === 15) {
        const mo = rec(p, 7, d0);
        const nf = pw(p, mo);
        const np = pw(p, mo + 1);
        const na = pw(p, mo + 2);
        const nl = pw(p, mo + 3);
        const pb = (mo + 8) + (4 * nf);
        const lb = (pb + (5 * np)) + (5 * na);
        if (i < nl) {
            return pw(p, (lb + (4 * i)) + 1);
        }
        // then every key and value typeset of every residual pool's group
        let j = i - nl;
        for (let q = 0; q < np; q++) {
            const g = pw(p, (pb + (5 * q)) + 1);
            if (g >= 0) {
                const go = rec(p, 5, g);
                const gn = pw(p, go);
                if (j < (2 * gn)) {
                    return pw(p, (go + 2) + ((4 * (j >> 1)) + (j & 1)));
                }
                j -= 2 * gn;
            }
        }
        return -2;
    }
    return -2;
}

export function childrenWithin(p, s, cs, e) {
    // Is every child (closed) of every leaf of cset cs marked e?
    const co = rec(p, 16, cs);
    const n = pw(p, co);
    for (let i = 0; i < n; i++) {
        const l = pw(p, co + (3 + i));
        let j = 0;
        for (;;) {
            if (!spend(s, 1)) {
                return false;
            }
            const t = childTs(p, l, j);
            if (t === (-2)) {
                break;
            }
            if (!inRange(t, pw(p, W_N_TYPESETS))) {
                return false;
            }
            if (!tsWithin(p, s, t, e)) {
                return false;
            }
            j += 1;
        }
    }
    return true;
}

export function hasChildren(p, cs) {
    const co = rec(p, 16, cs);
    const n = pw(p, co);
    for (let i = 0; i < n; i++) {
        const l = pw(p, co + (3 + i));
        if (childTs(p, l, 0) !== (-2)) {
            const t0 = childTs(p, l, 0);
            // a child typeset that is empty is no child at all
            if (inRange(t0, pw(p, W_N_TYPESETS)) && (tsEvalN(p, t0) > 0)) {
                return true;
            }
            let j = 1;
            for (;;) {
                const t = childTs(p, l, j);
                if (t === (-2)) {
                    break;
                }
                if (inRange(t, pw(p, W_N_TYPESETS)) && (tsEvalN(p, t) > 0)) {
                    return true;
                }
                j += 1;
            }
        }
    }
    return false;
}

export function csetFrame(p, co, n) {
    // frame_words of the cset at co (program.md §12.2).
    let maparea = 0;
    let arrarea = 0;
    for (let i = 0; i < n; i++) {
        const l = pw(p, co + (3 + i));
        const o = leafAt(p, l);
        const k = pw(p, o) & 255;
        if (k === 15) {
            const mo = rec(p, 7, pw(p, o + 2));
            maparea += pw(p, mo + 6) + (4 * pw(p, mo + 7));
        }
        if (k === 14) {
            const ao = rec(p, 9, pw(p, o + 2));
            arrarea += 3 + ((2 * pw(p, ao + 1)) + pw(p, ao + 2));
        }
    }
    if (arrarea > maparea) {
        maparea = arrarea;
    }
    return (2 * n) + maparea;
}

export function csetRegex(p, co, n) {
    let w = 0;
    for (let i = 0; i < n; i++) {
        const l = pw(p, co + (3 + i));
        const o = leafAt(p, l);
        if (((pw(p, o) & 255) === 8) && (pw(p, o + 4) >= 0)) {
            const ro = rec(p, 11, pw(p, o + 4));
            w += 2 * pw(p, ro + 1);
        }
    }
    return w;
}

export function checkCsets(p, s) {
    const nc = pw(p, W_N_CSETS);
    const nl = pw(p, W_N_LEAVES);
    for (let c = 0; c < nc; c++) {
        const co = rec(p, 16, c);
        const n = pw(p, co);
        const e = epoch(s);
        if (!spend(s, 1 + n)) {
            return false;
        }
        for (let i = 0; i < n; i++) {
            const l = pw(p, co + (3 + i));
            if (!inRange(l, nl)) {
                return want(s, false, co + (3 + i), C_CSET);
            }
            if ((i > 0) && (l <= pw(p, co + (2 + i)))) {
                return want(s, false, co + (3 + i), C_CSET);
            }
            markSet(s, l, e);
        }
        // closed under combinator operands
        for (let j = 0; j < n; j++) {
            const l2 = pw(p, co + (3 + j));
            if (combinator(p, l2)) {
                const lo = leafAt(p, l2);
                if ((markGet(s, pw(p, lo + 2)) !== e) || (markGet(s, pw(p, lo + 3)) !== e)) {
                    return want(s, false, co + (3 + j), C_CSET);
                }
            }
        }
        if (pw(p, co + 1) !== csetFrame(p, co, n)) {
            return want(s, false, co + 1, C_DERIVED);
        }
        if (pw(p, co + 2) !== csetRegex(p, co, n)) {
            return want(s, false, co + 2, C_DERIVED);
        }
    }
    return !failed(s);
}

export function checkChains(p, s) {
    const nch = pw(p, W_N_CHAINS);
    const ncs = pw(p, W_N_CSETS);
    const d = pw(p, 32);
    for (let c = 0; c < nch; c++) {
        const o = rec(p, 18, c);
        const n = pw(p, o);
        const r = pw(p, o + 1);
        if (n > (d + 1)) {
            return want(s, false, o, C_CHAIN);
        }
        if ((r < (-1)) || (r >= n)) {
            return want(s, false, o, C_CHAIN);
        }
        for (let i = 0; i < n; i++) {
            if (!inRange(pw(p, o + (2 + i)), ncs)) {
                return want(s, false, o + (2 + i), C_CHAIN);
            }
        }
        // cset[k+1] holds the children of cset[k]; the period closes; an
        // ending chain ends with no children
        for (let k = 0; k < n - 1; k++) {
            const e = epoch(s);
            const nxt = pw(p, o + (3 + k));
            const no = rec(p, 16, nxt);
            for (let q = 0; q < pw(p, no); q++) {
                markSet(s, pw(p, no + (3 + q)), e);
            }
            if (!childrenWithin(p, s, pw(p, o + (2 + k)), e)) {
                return want(s, false, o + (2 + k), C_CHAIN);
            }
        }
        if (r >= 0) {
            const e2 = epoch(s);
            const rc = pw(p, o + (2 + r));
            const ro = rec(p, 16, rc);
            for (let q2 = 0; q2 < pw(p, ro); q2++) {
                markSet(s, pw(p, ro + (3 + q2)), e2);
            }
            if (!childrenWithin(p, s, pw(p, o + (2 + (n - 1))), e2)) {
                return want(s, false, o, C_CHAIN);
            }
        } else if (n <= d) {
            if (hasChildren(p, pw(p, o + (2 + (n - 1))))) {
                return want(s, false, o, C_CHAIN);
            }
        }
    }
    return !failed(s);
}

export function ruleScratch(p, chain) {
    // program.md §12.1's scratch words for a rule with this chain (MARK_CAP =
    // N_LEAVES).
    const o = rec(p, 18, chain);
    const n = pw(p, o);
    const r = pw(p, o + 1);
    const d = pw(p, 32);
    const nl = pw(p, W_N_LEAVES);
    let sumf = 0;
    let maxr = 0;
    for (let k = 0; k < d + 1; k++) {
        let idx = k;
        if (k >= n) {
            if (r < 0) {
                idx = -1;
            } else {
                idx = r + ((k - r) - ((((k - r) / (n - r)) | 0) * (n - r)));
            }
        }
        if (idx >= 0) {
            const co = rec(p, 16, pw(p, o + (2 + idx)));
            sumf += pw(p, co + 1);
            if (pw(p, co + 2) > maxr) {
                maxr = pw(p, co + 2);
            }
        }
    }
    return ((48 + (2 * nl)) + (2 * (d + 1))) + (maxr + sumf);
}

export function checkRuleClosure(p, s) {
    // R_0 holds the rule's evaluation list; scratch_words; SCRATCH_MAX; flags;
    // the total-bytes cap.
    const base = sec(p, 0);
    const nr = pw(p, W_N_RULES);
    let smax = 0;
    for (let i = 0; i < nr; i++) {
        const o = base + (5 * i);
        const t = pw(p, o + 2);
        const ch = pw(p, o + 3);
        const co = rec(p, 18, ch);
        const c0 = pw(p, co + 2);
        const c0o = rec(p, 16, c0);
        const e = epoch(s);
        if (!spend(s, pw(p, c0o))) {
            return false;
        }
        for (let q = 0; q < pw(p, c0o); q++) {
            markSet(s, pw(p, c0o + (3 + q)), e);
        }
        if (!tsWithin(p, s, t, e)) {
            return want(s, false, o, C_CHAIN);
        }
        const sw = ruleScratch(p, ch);
        if (pw(p, o + 4) !== sw) {
            return want(s, false, o + 4, C_DERIVED);
        }
        if (sw > smax) {
            smax = sw;
        }
    }
    if (pw(p, 40) !== smax) {
        return want(s, false, 40, C_DERIVED);
    }
    const total = pw(p, 38);
    const words = p.length;
    const pool = pw(p, 4);
    if ((smax > ((total / 4) | 0)) || (words > ((((total - pool) - (4 * smax)) / 4) | 0))) {
        return want(s, false, 38, C_TOTAL);
    }
    return !failed(s);
}

export function checkFlags(p, b, s) {
    let f = 0;
    let needsAny = false;
    for (let kq = 0; kq < pw(p, W_N_KEYS); kq++) {
        const ko = pw(p, sec(p, 4) + (2 * kq));
        if (((b[ko] >>> 5) | 0) <= 1) {
            f |= 1;
        }
    }
    for (let l = 0; l < pw(p, W_N_LEAVES); l++) {
        const o = leafAt(p, l);
        const k = pw(p, o) & 255;
        if ((k === 8) && (pw(p, o + 4) >= 0)) {
            f |= 2;
        }
        if (k === 13) {
            f |= 4;
        }
        if ((k === 16) || (k === 17)) {
            f |= 8;
        }
        if (k === 18) {
            f |= 16;
        }
        if ((k === 1) || ((k === 2) && ((pw(p, o + 2) >= 4) && (pw(p, o + 2) <= 6)))) {
            needsAny = true;
        }
    }
    if (pw(p, 6) !== f) {
        return want(s, false, 6, C_DERIVED);
    }
    if (needsAny && (pw(p, W_TS_ANY) < 0)) {
        return want(s, false, W_TS_ANY, C_HEADER);
    }
    return true;
}

export function nameByteOk(c, first) {
    // A control name: ASCII letters and `_`, then also digits and `-`.
    if (((c >= 65) && (c <= 90)) || (((c >= 97) && (c <= 122)) || (c === 95))) {
        return true;
    }
    if (first) {
        return false;
    }
    return ((c >= 48) && (c <= 57)) || (c === 45);
}

export function checkExts(p, b, s) {
    // The names of the N_EXTS extension controls: deterministic CBOR text
    // strings of 1..64 name bytes, strictly ascending bytewise, back to back
    // filling pool[W_EXT_NAMES, + W_EXT_NAMES_LEN) exactly; none without any.
    const n = pw(p, W_N_EXTS);
    const off = pw(p, W_EXT_NAMES);
    const len = pw(p, W_EXT_NAMES_LEN);
    if (n === 0) {
        return want(s, (off === 0) && (len === 0), W_EXT_NAMES, C_EXT);
    }
    if (!want(s, byteRange(b, off, len), W_EXT_NAMES, C_EXT)) {
        return false;
    }
    if (!spend(s, n + ((len / 4) | 0))) {
        return false;
    }
    const end = off + len;
    let i = off;
    let po = -1;
    let pl = 0;
    for (let _k = 0; _k < n; _k++) {
        if (i >= end) {
            return want(s, false, W_EXT_NAMES, C_EXT);
        }
        const ib = b[i];
        let nl = ib & 31;
        let c = i + 1;
        if (((ib >>> 5) | 0) !== 3) {
            return want(s, false, W_EXT_NAMES, C_EXT);
        }
        if (nl > 24) {
            return want(s, false, W_EXT_NAMES, C_EXT);
        }
        if (nl === 24) {
            if (c >= end) {
                return want(s, false, W_EXT_NAMES, C_EXT);
            }
            nl = b[c];
            if (nl < 24) {
                return want(s, false, W_EXT_NAMES, C_EXT);
            }
            c += 1;
        }
        if ((nl < 1) || ((nl > 64) || (nl > (end - c)))) {
            return want(s, false, W_EXT_NAMES, C_EXT);
        }
        for (let j = 0; j < nl; j++) {
            if (!nameByteOk(b[c + j], j === 0)) {
                return want(s, false, W_EXT_NAMES, C_EXT);
            }
        }
        if ((po >= 0) && (bytesCmp(b, po, pl, c, nl) >= 0)) {
            return want(s, false, W_EXT_NAMES, C_EXT);
        }
        po = c;
        pl = nl;
        i = c + nl;
    }
    return want(s, i === end, W_EXT_NAMES, C_EXT);
}

export function vmVerify(p, b, s) {
    // 0 valid; -1 refused (detail in S[35], S[36]); -2 the scratch is too small
    // for the verifier's marks (len(S) >= 48 + 2 * VM_MARK_CAP, VM_MARK_CAP >=
    // N_LEAVES).
    if (s.length < 48) {
        return -2;
    }
    s[V_FAILED] = 0;
    s[VM_DETAIL] = 0;
    s[VM_DETAIL + 1] = 0;
    if (!checkHeader(p, b, s)) {
        return -1;
    }
    const m = s[VM_MARK_CAP];
    const nl = p[W_N_LEAVES];
    if ((m < nl) || ((m < 0) || ((48 + (2 * m)) > s.length))) {
        return -2;
    }
    // the verify budget: 64 * (PROGRAM_WORDS + POOL_BYTES / 4 + 1)
    const units = (p.length + ((b.length / 4) | 0)) + 1;
    if (units > ((INF / 64) | 0)) {
        s[V_BUDGET] = INF;
    } else {
        s[V_BUDGET] = 64 * units;
    }
    if (!checkIndex(p, s, 2, 3, pw(p, W_N_TYPESETS), 0)) {
        return -1;
    }
    if (!checkIndex(p, s, 5, 6, pw(p, W_N_GROUPS), 1)) {
        return -1;
    }
    if (!checkIndex(p, s, 7, 8, pw(p, W_N_MAPS), 2)) {
        return -1;
    }
    if (!checkIndex(p, s, 9, 10, pw(p, W_N_ARRAYS), 3)) {
        return -1;
    }
    if (!checkIndex(p, s, 11, 12, pw(p, W_N_REGEXPS), 4)) {
        return -1;
    }
    if (!checkIndex(p, s, 16, 17, pw(p, W_N_CSETS), 5)) {
        return -1;
    }
    if (!checkIndex(p, s, 18, 19, pw(p, W_N_CHAINS), 6)) {
        return -1;
    }
    if (!checkExts(p, b, s)) {
        return -1;
    }
    if (!checkIvRecords(p, b, s)) {
        return -1;
    }
    if (!checkLeaves(p, b, s)) {
        return -1;
    }
    if (!checkTypesets(p, s)) {
        return -1;
    }
    if (!checkKeys(p, b, s)) {
        return -1;
    }
    if (!checkGroups(p, s)) {
        return -1;
    }
    if (!checkRules(p, b, s)) {
        return -1;
    }
    if (!checkMaps(p, s)) {
        return -1;
    }
    if (!checkArrays(p, s)) {
        return -1;
    }
    if (!checkRegexps(p, s)) {
        return -1;
    }
    if (!checkFlags(p, b, s)) {
        return -1;
    }
    if (!checkCsets(p, s)) {
        return -1;
    }
    if (!checkChains(p, s)) {
        return -1;
    }
    if (!checkRuleClosure(p, s)) {
        return -1;
    }
    if (failed(s)) {
        return -1;
    }
    return 0;
}
